// New in R2c: no old counterpart (the old tree had two decoders that each decoded the ampersand first and knew six names, register rows C:6 and D:87).
// The one character-reference decoder for captured markup and for XML: a single pass, so a reference is decoded once and the result is never rescanned (`&amp;lt;` is the text `&lt;`). The named table is the HTML5 set
// (data/entities.json, generated by scripts/gen/html-entities.mjs); a numeric reference outside Unicode, a surrogate or zero is U+FFFD; the C1 range reads as windows-1252 as a browser does; an unknown name stays literal.
import table from "./data/entities.json";

const NAMED = table as Record<string, string>;
const REFERENCE = /&(?:#[xX]([0-9a-fA-F]{1,8})|#([0-9]{1,10})|([A-Za-z][A-Za-z0-9]{1,31}));/g;
const REPLACEMENT = "�";
const cp1252 = new TextDecoder("windows-1252");

function fromCodePoint(n: number): string {
  if (n === 0 || n > 0x10ffff || (n >= 0xd800 && n <= 0xdfff)) return REPLACEMENT;
  return n >= 0x80 && n <= 0x9f ? cp1252.decode(Uint8Array.of(n)) : String.fromCodePoint(n);
}

/** Decode every character reference in `s` exactly once. */
export function decodeEntities(s: string): string {
  return s.replace(REFERENCE, (match, hex?: string, dec?: string, name?: string) => (hex !== undefined ? fromCodePoint(parseInt(hex, 16)) : dec !== undefined ? fromCodePoint(Number(dec)) : (NAMED[name as string] ?? match)));
}

/**
 * Markup to text in one linear pass: comments (to their end, or to the end of the document when unterminated), then tags, with a `>` inside a quoted attribute value kept inside the tag. A `<` that does not open a tag
 * (`a < b`) stays text. Each removed tag leaves a space, so adjacent words never fuse.
 */
export function stripTags(html: string): string {
  let out = "";
  let i = 0;
  const n = html.length;
  while (i < n) {
    const lt = html.indexOf("<", i);
    if (lt < 0) return out + html.slice(i);
    out += html.slice(i, lt);
    if (html.startsWith("<!--", lt)) {
      const end = html.indexOf("-->", lt + 4);
      out += " ";
      i = end < 0 ? n : end + 3;
      continue;
    }
    const c = html[lt + 1] ?? "";
    if (!/[A-Za-z/!?]/.test(c)) {
      out += "<";
      i = lt + 1;
      continue;
    }
    let j = lt + 1;
    let quote = "";
    for (; j < n; j++) {
      const ch = html[j] as string;
      if (quote) quote = ch === quote ? "" : quote;
      else if (ch === '"' || ch === "'") quote = ch;
      else if (ch === ">") break;
    }
    out += " ";
    i = j + 1;
  }
  return out;
}
